"""The campaign byte regular language, implemented without backtracking.

Python's regex syntax is not the protocol syntax (notably '.', '$', repeated
stars, and empty alternatives). A small parser and epsilon-NFA avoid both those
semantic differences and exponential running time on nullable repetitions.
"""
from functools import lru_cache


class Regex:
    def matches(self, string):
        if not hasattr(self, "_machine"):
            self._machine = _NFA(self)
        return self._machine.matches(string)


class Empty(Regex):
    def __str__(self):
        return ""


class Range(Regex):
    def __init__(self, low, high):
        self.low, self.high = low, high

    def __str__(self):
        return "[" + _escape_class(self.low) + "-" + _escape_class(self.high) + "]"


class Choice(Regex):
    def __init__(self, *args):
        self.exprs = args

    def __str__(self):
        return "(" + "|".join(map(str, self.exprs)) + ")"


class Seq(Regex):
    def __init__(self, *args):
        self.exprs = args

    def __str__(self):
        return "(" + "".join(map(str, self.exprs)) + ")"


class Star(Regex):
    def __init__(self, expr):
        self.expr = expr

    def __str__(self):
        return "(" + str(self.expr) + ")*"


def _escape_class(char):
    return "\\" + char if char in "-]\\" else char


def chars(low, high):
    return Range(low, high)


def text(string):
    return Seq(*(Range(c, c) for c in string))


def choice(*args):
    return Choice(*args)


def seq(*args):
    return Seq(*args)


def star(expr):
    return Star(expr)


def plus(expr):
    return Seq(expr, Star(expr))


def empty():
    return Empty()


def ismatch(regex, string):
    return regex.matches(string)


@lru_cache(maxsize=4096)
def parse(pattern):
    """Recursive descent: union < sequence < repeated atom."""
    position = 0

    def literal():
        nonlocal position
        char = pattern[position]
        position += 1
        if char == "\\":
            char = pattern[position]
            position += 1
        return char

    def union():
        nonlocal position
        alternatives = [sequence()]
        while position < len(pattern) and pattern[position] == "|":
            position += 1
            alternatives.append(sequence())
        return alternatives[0] if len(alternatives) == 1 else Choice(*alternatives)

    def sequence():
        nonlocal position
        atoms = []
        while position < len(pattern) and pattern[position] not in "|)":
            char = pattern[position]
            if char == "(":
                position += 1
                atom = union()
                assert pattern[position] == ")"
                position += 1
            elif char == "[":
                position += 1
                items = []
                while pattern[position] != "]":
                    low = literal()
                    if pattern[position] == "-":
                        position += 1
                        high = literal()
                    else:
                        high = low
                    items.append(Range(low, high))
                position += 1
                atom = items[0] if len(items) == 1 else Choice(*items)
            else:
                char = literal()
                atom = Range(char, char)
            while position < len(pattern) and pattern[position] == "*":
                position += 1
                atom = Star(atom)
            atoms.append(atom)
        return atoms[0] if len(atoms) == 1 else Seq(*atoms)

    result = union()
    assert position == len(pattern)
    return result


class _NFA:
    def __init__(self, regex):
        self.epsilon = []
        self.edges = []

        def state():
            index = len(self.edges)
            self.edges.append(None)
            self.epsilon.append([])
            return index

        def build(expr):
            start, end = state(), state()
            if isinstance(expr, Range):
                self.edges[start] = (ord(expr.low), ord(expr.high), end)
            elif isinstance(expr, (Empty, Seq)):
                current = start
                for child in getattr(expr, "exprs", ()):
                    a, b = build(child)
                    self.epsilon[current].append(a)
                    current = b
                self.epsilon[current].append(end)
            elif isinstance(expr, Choice):
                for child in expr.exprs:
                    a, b = build(child)
                    self.epsilon[start].append(a)
                    self.epsilon[b].append(end)
            elif isinstance(expr, Star):
                a, b = build(expr.expr)
                self.epsilon[start].extend((a, end))
                self.epsilon[b].extend((a, end))
            else:
                raise TypeError("unknown regex node")
            return start, end

        start, self.end = build(regex)
        self.closures = {}
        self.initial = self.closure(start)
        self.accept = 1 << self.end
        self.steps = {}

    def closure(self, start):
        cached = self.closures.get(start)
        if cached is not None:
            return cached
        visited = 0
        active = 0
        pending = [start]
        while pending:
            node = pending.pop()
            bit = 1 << node
            if visited & bit:
                continue
            visited |= bit
            # Only consuming states and the accepting state need to be retained.
            if self.edges[node] is not None or node == self.end:
                active |= bit
            pending.extend(self.epsilon[node])
        self.closures[start] = active
        return active

    def matches(self, string):
        active = self.initial
        for char in string:
            code = ord(char)
            key = (active, code)
            result = self.steps.get(key)
            if result is None:
                remaining = active
                result = 0
                while remaining:
                    bit = remaining & -remaining
                    remaining -= bit
                    edge = self.edges[bit.bit_length() - 1]
                    if edge is not None and edge[0] <= code <= edge[1]:
                        result |= self.closure(edge[2])
                # Bound the optional lazy DFA cache; NFA execution is always
                # available if a language has exponentially many subsets.
                if len(self.steps) < 4096:
                    self.steps[key] = result
            active = result
            if not active:
                return False
        return bool(active & self.accept)
